import{_ as o}from"./chunks/z-stack-time-laps-navigation.DWNnv26e.js";import{_ as r}from"./chunks/plate-navigation.DRgsKBSY.js";import{_ as i,c as n,o as l,j as e,ag as t,a as s}from"./chunks/framework.DZ_cNctr.js";const d="/docs/screenshots/open-url.png",h="/docs/screenshots/channel-controls.png",c="/docs/screenshots/label-controls.png",x=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started.md","filePath":"getting-started.md"}'),p={name:"getting-started.md"};function g(u,a,m,b,f,w){return l(),n("div",null,[...a[0]||(a[0]=[e("h1",{id:"getting-started",tabindex:"-1"},[s("Getting Started "),e("a",{class:"header-anchor",href:"#getting-started","aria-label":'Permalink to "Getting Started"'},"​")],-1),e("p",null,"Find Nuclei Viewer is a browser-based viewer for OME-ZARR microscopy data. It runs entirely in your browser. No installation, no file uploads, no account required. Open local files or remote URLs and start exploring in seconds.",-1),e("div",{style:{position:"relative","padding-bottom":"56.25%",height:"0",overflow:"hidden",margin:"1.5rem 0"}},[e("iframe",{src:"https://www.youtube.com/embed/p9veMmibuWA?rel=0&modestbranding=1&vq=hd720&mute=1",title:"Open Your Microscopy Data in 10 Seconds",style:{position:"absolute",top:"0",left:"0",width:"100%",height:"100%",border:"0"},allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture",allowfullscreen:""})],-1),t('<h2 id="open-local-data" tabindex="-1">Open Local Data <a class="header-anchor" href="#open-local-data" aria-label="Permalink to &quot;Open Local Data&quot;">​</a></h2><p>The fastest way to get started is to drag and drop a local OME-ZARR folder directly into the browser.</p><ol><li>Go to <a href="https://find-nuclei.github.io" target="_blank" rel="noreferrer">find-nuclei.github.io</a></li><li>Open your file manager (Finder on macOS, Explorer on Windows)</li><li>Drag your <code>.ome.zarr</code> folder onto the browser window</li><li>The drop overlay appears. Release to open</li></ol><p>Your data stays on your machine. Nothing is uploaded anywhere.</p><div class="tip custom-block"><p class="custom-block-title">Keep it around</p><p>If you use the viewer often, Chrome and Edge can install it as an app: its own window, an icon in the Dock or Start menu, and it keeps working with no network. See <a href="/docs/install-and-offline.html">Installing and Offline</a>.</p></div><div class="tip custom-block"><p class="custom-block-title">Supported Formats</p><p>Find Nuclei Viewer supports <strong>OME-ZARR</strong> (OME-NGFF) format, versions 0.4 and 0.5, including sharded stores. Both single images and HCS plates are supported.</p></div><h2 id="open-remote-data" tabindex="-1">Open Remote Data <a class="header-anchor" href="#open-remote-data" aria-label="Permalink to &quot;Open Remote Data&quot;">​</a></h2><p>You can also open OME-ZARR datasets hosted on public servers like the <a href="https://idr.openmicroscopy.org" target="_blank" rel="noreferrer">Image Data Resource (IDR)</a>.</p><ol><li>Click the <strong>Open Image</strong> button on the landing page</li><li>The Load Data modal opens</li><li>Paste an OME-ZARR URL into the URL field (e.g., from IDR)</li><li>Click <strong>Load from URL</strong></li></ol><p>The viewer streams tiles directly from the remote server. No download required.</p><img src="'+d+'" alt="Open Image dialog with URL input" style="max-width:301px;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"><h2 id="open-an-example" tabindex="-1">Open an Example <a class="header-anchor" href="#open-an-example" aria-label="Permalink to &quot;Open an Example&quot;">​</a></h2><p>Not sure where to start? Click <strong>Open Example</strong> on the landing page to browse curated public datasets from the IDR.</p><h2 id="navigate-your-image" tabindex="-1">Navigate Your Image <a class="header-anchor" href="#navigate-your-image" aria-label="Permalink to &quot;Navigate Your Image&quot;">​</a></h2><p>Once your image is loaded:</p><table tabindex="0"><thead><tr><th>Action</th><th>Control</th></tr></thead><tbody><tr><td><strong>Zoom in/out</strong></td><td>Scroll wheel</td></tr><tr><td><strong>Pan</strong></td><td>Click and drag</td></tr><tr><td><strong>Reset view</strong></td><td>Double-click</td></tr></tbody></table><p>The viewer uses GPU-accelerated multi-resolution tile rendering via deck.gl WebGL. Zoom in and higher-resolution tiles load automatically. It handles images over 100,000 pixels wide.</p><h2 id="channel-controls" tabindex="-1">Channel Controls <a class="header-anchor" href="#channel-controls" aria-label="Permalink to &quot;Channel Controls&quot;">​</a></h2><p>Microscopy images often have multiple fluorescence channels. The channel panel on the right lets you:</p><ul><li><strong>Toggle channels</strong> on/off with the visibility checkbox</li><li><strong>Change channel color</strong> by clicking the color swatch</li><li><strong>Adjust contrast</strong> using the min/max sliders</li><li><strong>Auto-contrast</strong>: one-click percentile-based (2%–98%) intensity optimization per channel</li><li><strong>Per-channel histograms</strong>: see the intensity distribution for each channel</li></ul><img src="'+h+'" alt="Channel controls panel" style="max-width:320px;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"><p>All channels blend in real time using GPU-accelerated rendering.</p><h2 id="z-stack-navigation" tabindex="-1">Z-Stack Navigation <a class="header-anchor" href="#z-stack-navigation" aria-label="Permalink to &quot;Z-Stack Navigation&quot;">​</a></h2><p>If your image has multiple Z-slices, a <strong>Z-slider</strong> appears below the viewer. Drag it to navigate through the focal planes.</p><img src="'+o+'" alt="Z-stack and time-lapse navigation controls" style="max-width:205px;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"><h3 id="z-projection" tabindex="-1">Z-Projection <a class="header-anchor" href="#z-projection" aria-label="Permalink to &quot;Z-Projection&quot;">​</a></h3><p>A Z-stack can be flattened into a single image by maximum, mean or minimum intensity, over the whole stack or any range of planes you choose. Which mode you pick decides what stays visible, and on a deep stack the range decides how long you wait.</p><p>See the <a href="/docs/guides/z-projection.html">Z-Projection Guide</a> for which mode answers which question, and how to keep large stacks fast.</p><h2 id="segmentation-overlays" tabindex="-1">Segmentation Overlays <a class="header-anchor" href="#segmentation-overlays" aria-label="Permalink to &quot;Segmentation Overlays&quot;">​</a></h2><p>The viewer can display segmentation labels (masks) alongside your image data.</p><ul><li>Labels stored inside the OME-ZARR are detected automatically</li><li>Toggle label visibility in the <strong>Labels</strong> panel</li><li>Adjust label <strong>opacity</strong> with the slider</li><li>Each label instance gets a unique color</li><li><strong>Drag-to-reorder</strong> label layers for rendering priority</li></ul><img src="'+c+'" alt="Label controls panel" style="max-width:425px;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"><p>You can also link external label stores using the <strong>Link Label</strong> button. Load labels from your local disk or a remote URL.</p><h2 id="shape-annotations" tabindex="-1">Shape Annotations <a class="header-anchor" href="#shape-annotations" aria-label="Permalink to &quot;Shape Annotations&quot;">​</a></h2><p>Draw and measure directly on your images:</p><ul><li><strong>Polygons</strong>: outline regions of interest</li><li><strong>Lines</strong>: mark linear features</li><li><strong>Points</strong>: tag specific locations</li><li><strong>Distance measurements</strong>: measure between two points</li></ul><p>Annotations are <strong>auto-saved</strong> to browser storage and persist across sessions. Export your annotations as <strong>CSV spreadsheet</strong> or <strong>GeoJSON</strong> for downstream analysis.</p><h2 id="hcs-plates" tabindex="-1">HCS Plates <a class="header-anchor" href="#hcs-plates" aria-label="Permalink to &quot;HCS Plates&quot;">​</a></h2><p>Find Nuclei Viewer has full support for High-Content Screening (HCS) plate data. Any plate format works: 96, 384, 1536-well, or custom layouts.</p>',39),e("div",{style:{position:"relative","padding-bottom":"56.25%",height:"0",overflow:"hidden",margin:"1.5rem 0"}},[e("iframe",{src:"https://www.youtube.com/embed/tTUhXRHREnU?rel=0&modestbranding=1&vq=hd720&mute=1",title:"HCS Plate in Your Browser",style:{position:"absolute",top:"0",left:"0",width:"100%",height:"100%",border:"0"},allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture",allowfullscreen:""})],-1),t('<ul><li><strong>Field View</strong>: opens showing the first field of the first well</li><li><strong>Grid View</strong>: click <strong>Show All Fields</strong> to see all fields in the current well laid out in a grid</li><li><strong>Plate View</strong>: click <strong>Show Full Plate</strong> to see the entire plate overview with all wells</li><li><strong>Seamless zoom</strong>: zoom smoothly from plate overview all the way down to individual cells</li></ul><img src="'+r+'" alt="HCS plate navigation controls" style="max-width:425px;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"><p>Navigate between views by clicking wells in the plate overview. Channel settings apply plate-wide.</p><h2 id="share-a-view" tabindex="-1">Share a View <a class="header-anchor" href="#share-a-view" aria-label="Permalink to &quot;Share a View&quot;">​</a></h2><p>When viewing a remote (URL-based) dataset, the URL tracks your view state in real time, like Google Maps:</p><ol><li>Set up your view: zoom to a region, adjust channels and colors</li><li>Click the <strong>🔗 Link</strong> button in the toolbar</li><li>A shareable URL is copied to your clipboard</li><li>Send the link. The recipient sees the exact same view (zoom, position, channels, colors)</li></ol><p>The link works in any modern browser. No install needed for your collaborators.</p><h2 id="live-examples" tabindex="-1">Live Examples <a class="header-anchor" href="#live-examples" aria-label="Permalink to &quot;Live Examples&quot;">​</a></h2><p>Click any link to open directly in the viewer:</p><table tabindex="0"><thead><tr><th>Example</th><th>Description</th></tr></thead><tbody><tr><td><a href="https://find-nuclei.github.io/?url=https%3A%2F%2Fuk1s3.embassy.ebi.ac.uk%2Fidr%2Fzarr%2Fv0.4%2Fidr0079A%2Fidr0079_images.zarr&amp;z=71&amp;channels=0%3Aon%3A00FF00%3A8%3A90%2C1%3Aon%3AFF0000%3A7%3A80&amp;zoom=-0.57&amp;center=792%2C394" target="_blank" rel="noreferrer">Zebrafish Lateral Line</a></td><td>3D multi-channel with labels</td></tr><tr><td><a href="https://find-nuclei.github.io/?url=https%3A%2F%2Fuk1s3.embassy.ebi.ac.uk%2Fidr%2Fzarr%2Fv0.5%2Fidr0090%2F190129.zarr&amp;z=15&amp;channels=0%3Aoff%3AFFFFFF%3A617%3A1676%2C1%3Aon%3A0000FF%3A403%3A441%2C2%3Aoff%3A00FF00%3A109%3A148%2C3%3Aon%3AFF0000%3A113%3A254%2C4%3Aon%3A00FF00%3A132%3A720&amp;zoom=-1.38&amp;center=1024%2C1022" target="_blank" rel="noreferrer">HCS Plate (v0.5)</a></td><td>Multi-well plate, 5 channels</td></tr><tr><td><a href="https://find-nuclei.github.io/?url=https%3A%2F%2Fuk1s3.embassy.ebi.ac.uk%2Fidr%2Fzarr%2Fv0.4%2Fidr0083A%2F9822152.zarr&amp;z=0&amp;channels=0%3Aon%3Affffff%3A0%3A5193&amp;zoom=-7.08&amp;center=72192%2C46592" target="_blank" rel="noreferrer">Large Image (144K×93K)</a></td><td>144K×93K pixels, multi-resolution</td></tr></tbody></table><p>All datasets from the <a href="https://idr.openmicroscopy.org/" target="_blank" rel="noreferrer">Image Data Resource (IDR)</a>.</p><h2 id="what-s-next" tabindex="-1">What&#39;s Next? <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s Next?&quot;">​</a></h2><h3 id="open-and-organise" tabindex="-1">Open and organise <a class="header-anchor" href="#open-and-organise" aria-label="Permalink to &quot;Open and organise&quot;">​</a></h3><ul><li><a href="/docs/guides/local-files.html">Local Files Guide</a>: deep dive into local file workflows</li><li><a href="/docs/guides/remote-urls.html">Remote URLs Guide</a>: working with public and private Zarr stores</li><li><a href="/docs/guides/data-server.html">Data Server Guide</a>: host your own on-site Zarr server with <a href="https://hub.docker.com/r/fn0000/fn-data-server" target="_blank" rel="noreferrer">Docker</a></li><li><a href="/docs/guides/hcs-plates.html">HCS Plates Guide</a>: plate navigation and multi-well analysis</li></ul><h3 id="work-with-your-data" tabindex="-1">Work with your data <a class="header-anchor" href="#work-with-your-data" aria-label="Permalink to &quot;Work with your data&quot;">​</a></h3><ul><li><a href="/docs/guides/labels.html">Labels Guide</a>: load segmentation masks, control display, organise by source or metadata</li><li><a href="/docs/guides/annotations.html">Annotations Guide</a>: draw, multi-select with lasso, classify with templates, bulk-edit</li><li><a href="/docs/guides/analytics-phenotyping.html">Analytics &amp; Phenotyping Guide</a>: load measurement CSVs, color by column, build cell populations</li></ul><h3 id="share-and-embed" tabindex="-1">Share and embed <a class="header-anchor" href="#share-and-embed" aria-label="Permalink to &quot;Share and embed&quot;">​</a></h3><ul><li><a href="/docs/guides/sharing.html">Sharing Guide</a>: URL sharing and collaboration</li><li><a href="/docs/guides/embedding.html">Embedding Guide</a>: drop the viewer into any web page with two lines of HTML</li></ul>',18)])])}const A=i(p,[["render",g]]);export{x as __pageData,A as default};
